def _kq_special_rows(*, claims: ClaimCollection):
    cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.kq-special.subtype-counts",
    )
    return cmn.emit_claim_by_id(
        claims=claims,
        claim_id="mp.both.templates.kq-special.subtypes",
    )


